// Supabase Edge Function `seald`: the whole Nest API in one function
// (AWS exit plan, WS-0). `dist/` is generated by
// `pnpm --filter api build:edge`; see apps/api/scripts/build-edge.mjs.
import { ASSET_ROOT, installAssetFs } from './asset-fs.ts';
import assets from './dist/assets.mjs';

installAssetFs(assets as Record<string, string>);
(globalThis as { __SEALD_ASSET_DIR?: string }).__SEALD_ASSET_DIR = ASSET_ROOT;

const { bootstrapEdge } = await import('./dist/edge.mjs');
await bootstrapEdge('seald');
